Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "fold": [
        "Energética (ENE)",
        "Confiabilidade (CNF)",
        "Indisponibilidade externa (REL)",
        "Parecer de acesso (PAR)",
        "Sem razão (GWh)",
        "Origem local (GWh)",
        "Origem sistêmica (GWh)",
        "Sem origem (GWh)"
      ],
      "as": [
        "medida",
        "gwh"
      ]
    },
    {
      "calculate": "datum.medida == ''Energética (ENE)'' ? ''ENE'' : datum.medida == ''Confiabilidade (CNF)'' ? ''CNF'' : datum.medida == ''Indisponibilidade externa (REL)'' ? ''REL'' : datum.medida == ''Parecer de acesso (PAR)'' ? ''PAR'' : datum.medida == ''Sem razão (GWh)'' ? ''Sem razão'' : datum.medida == ''Origem local (GWh)'' ? ''Local'' : datum.medida == ''Origem sistêmica (GWh)'' ? ''Sistêmica'' : datum.medida == ''Sem origem (GWh)'' ? ''Sem origem'' : ''''",
      "as": "cat"
    },
    {
      "calculate": "indexof([''Local'',''Sistêmica'',''Sem origem''], datum.cat) >= 0 ? ''Origem'' : ''Razão''",
      "as": "grupo"
    },
    {
      "calculate": "indexof([\"ENE\", \"CNF\", \"REL\", \"PAR\", \"Sem razão\", \"Local\", \"Sistêmica\", \"Sem origem\"], datum.cat)",
      "as": "ordem"
    },
    {
      "calculate": "datum.gwh || 0",
      "as": "gwh"
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "gwh",
          "as": "tot"
        }
      ],
      "groupby": [
        "grupo"
      ]
    },
    {
      "calculate": "datum.tot > 0 ? datum.gwh / datum.tot : 0",
      "as": "pct"
    },
    {
      "window": [
        {
          "op": "sum",
          "field": "pct",
          "as": "fim"
        }
      ],
      "groupby": [
        "grupo"
      ],
      "sort": [
        {
          "field": "ordem"
        }
      ],
      "frame": [
        null,
        0
      ]
    },
    {
      "calculate": "datum.fim - datum.pct",
      "as": "ini"
    },
    {
      "calculate": "datum.fim - datum.pct / 2",
      "as": "meio"
    }
  ],
  "encoding": {
    "y": {
      "field": "grupo",
      "type": "nominal",
      "title": null,
      "sort": [
        "Razão",
        "Origem"
      ],
      "axis": {
        "labelFontSize": 11,
        "labelColor": "#191919",
        "labelFontWeight": "bold",
        "ticks": false
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "height": {
          "band": 0.62
        }
      },
      "encoding": {
        "x": {
          "field": "ini",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "domain": [
              0,
              1
            ]
          }
        },
        "x2": {
          "field": "fim"
        },
        "color": {
          "field": "cat",
          "type": "nominal",
          "scale": {
            "domain": [
              "ENE",
              "CNF",
              "REL",
              "PAR",
              "Sem razão",
              "Local",
              "Sistêmica",
              "Sem origem"
            ],
            "range": [
              "#252423",
              "#605E5C",
              "#A19F9D",
              "#967100",
              "#E1DFDD",
              "#F2C811",
              "#191919",
              "#E1DFDD"
            ]
          },
          "legend": {
            "orient": "bottom",
            "columns": 4,
            "title": null,
            "labelFontSize": 9,
            "symbolSize": 60,
            "columnPadding": 8
          }
        },
        "tooltip": [
          {
            "field": "grupo",
            "title": "Grupo"
          },
          {
            "field": "cat",
            "title": "Categoria"
          },
          {
            "field": "gwh",
            "title": "GWh",
            "format": ",.1f"
          },
          {
            "field": "pct",
            "title": "Participação",
            "format": ".1%"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "datum.pct >= 0.07"
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 10,
        "fontWeight": "bold",
        "align": "center"
      },
      "encoding": {
        "x": {
          "field": "meio",
          "type": "quantitative"
        },
        "text": {
          "field": "pct",
          "format": ".0%"
        },
        "color": {
          "condition": {
            "test": "indexof([''ENE'',''CNF'',''Sistêmica'',''PAR''], datum.cat) >= 0",
            "value": "#FFFFFF"
          },
          "value": "#191919"
        }
      }
    }
  ]
}'
